variables.input_key:
{# One logical input stream per room; each source keeps a bounded snapshot.
   The most recent snapshot includes preceding inputs from the room's other
   remotes, so alternating devices cannot drop or apply a click twice. #}
{% macro latest_remote_key(records,room) -%}
 {% set pick=namespace(key='',stamp=-1) %}
 {% for key,r in records|dictsort if r is mapping and r.get('scope')=='room' and r.get('target')==room and (r.get('kind')=='input' or (r.get('kind')=='channels' and r.get('via')=='remote')) %}
  {% set stamp=as_timestamp(r.get('when'),0) %}
  {% if stamp>=pick.stamp %}{% set pick.key=key %}{% set pick.stamp=stamp %}{% endif %}
 {% endfor %}
 {{- pick.key|to_json -}}
{%- endmacro %}

{{ latest_remote_key(overrides,room)|from_json }}

variables.timing_revision:
{# No clock/schedule expansion: only versions of the room's expiry dependencies. #}
{% if command in ['up','down'] and is_state('input_boolean.ls_ovr_next_block_on','on') %}
 {% set n=namespace(ids=['input_boolean.ls_ovr_next_block_on']) %}
 {% for scope in ['house',room] %}
  {% for block in ['day','cosy','night'] %}
   {% set n.ids=n.ids+['input_boolean.ls_'~scope~'_'~block~'_own_timing','input_datetime.ls_'~scope~'_'~block~'_start','input_datetime.ls_'~scope~'_'~block~'_weekend','input_number.ls_'~scope~'_'~block~'_fade'] %}
  {% endfor %}
 {% endfor %}
 {% set version=namespace(latest=0) %}
 {% for entity in n.ids if states[entity] is not none %}
  {% set version.latest=[version.latest,as_timestamp(states[entity].last_updated,0)]|max %}
 {% endfor %}
 {{ version.latest }}
{% else %}{{ 0 }}{% endif %}

variables.result:
{# Button-domain state. No brightness, colour, gradient evaluation or effect ownership here.
   Compact composition represents x -> clamp(x+steps,lower,upper), in remote ticks.
   Lower/upper retain saturation history: a down click after many ups responds immediately. #}
{% set key='channels:'~source %}
{% set old=input_record|default(overrides.get(key,{})) %}
{% set old=old if old.get('scope')=='room' and old.get('target')==room and input_key|default(key) not in current.plan.get('stale_keys',[]) else {} %}
{% set value=old.get('value',{}) %}{% set value=value if value is mapping else {} %}
{% set n=namespace(result={'op':'noop'},value=value) %}
{% if room and command in ['up','down','left','right','toggle','reset','sara_toggle'] %}
 {% if command=='sara_toggle' %}
  {% set n.result={'op':'clear','keys':['mode:sara'],'via':'remote'} if 'mode:sara' in overrides else {'op':'set','records':[{'kind':'mode','target':'sara','value':'on'}],'via':'remote'} %}
 {% elif command=='toggle' %}
  {% set ids=namespace(v=[]) %}
  {% for L in catalog.members if area_id(L)==room %}{% set ids.v=ids.v+[L] %}{% endfor %}
  {% for L in (state_attr('sensor.ls_overrides','switch_ranges') or {}) if area_id(L)==room %}{% set ids.v=ids.v+[L] %}{% endfor %}
  {% set saved=(state_attr('sensor.ls_overrides','power') or {}).get(room) %}
  {% set on=not saved if saved is boolean else not (ids.v|select('is_state','on')|list|count>0) %}
  {% set n.result={'op':'power','area':room,'on':on,'targets':ids.v,'via':'remote'} %}
 {% elif command=='reset' %}
  {% set n.result={'op':'clear_room','area':room,'via':'remote'} %}
 {% else %}
  {% set identity={'steps':0,'lower':-20,'upper':20,'anchor':'current','updated':stamp} %}
  {% set a=namespace(v=value.get('adjustment'),restart=false) %}
  {% if a.v is not mapping %}
   {% set a.v=dict(identity,updated=as_timestamp(old.get('when'),0)) %}
   {# One-time compatibility for already-persisted pre-input remote coordinates. #}
   {% if old.get('kind')=='channels' and value.get('position') is number %}
    {% set a.v=dict(a.v,legacy_position=value.position) %}
   {% endif %}
  {% endif %}
  {% for other,r in overrides.items() if other!=key and r is mapping %}
   {% set applies=(r.get('scope')=='room' and r.get('target')==room) or (r.get('scope')=='house' and r.get('target')=='house' and room not in label_areas('private_room')) %}
   {% set v=r.get('value',{}) %}
   {% if applies and v is mapping %}
    {% set claim=v.get('channels',{}).get('brightness',{}) %}
    {% set newer=claim.get('updated',as_timestamp(r.get('when'),0)) if claim else v.get('adjustment',{}).get('updated',0) if v.get('adjustment') is mapping else 0 %}
    {% if newer>a.v.get('updated',0) %}{% set a.restart=true %}{% endif %}
   {% endif %}
  {% endfor %}
  {% if a.restart %}{% set a.v=identity %}{% endif %}
  {# Input records are replaced as a whole; never merge old interpreted channel claims. #}
  {% set n.value=dict(value.items()|rejectattr(0,'in',['channels','position'])|list) %}
  {# Retain the original effect claim/instance and its carried baseline while
     migrating a pre-input record. Its timestamps must never become this click. #}
  {% if old.get('kind')=='channels' and value.get('channels',{}).values()|selectattr('kind','eq','effect')|list|count>0 %}
   {% set n.value=dict(n.value,legacy_channels=value.channels) %}
  {% endif %}
  {% if command in ['up','down'] %}
   {% set d=1 if command=='up' else -1 %}
   {% set lo=[-20,[20,a.v.lower+d]|min]|max %}{% set hi=[-20,[20,a.v.upper+d]|min]|max %}
   {% set a.v=dict(a.v,steps=(0 if lo==hi else a.v.steps+d),lower=lo,upper=hi,updated=stamp,last=command,has_up=a.v.get('has_up',false) or command=='up') %}
   {% set n.value=dict(n.value,adjustment=a.v) %}
  {% else %}
   {% set n.value=dict(n.value.items()|rejectattr(0,'eq','legacy_channels')|list) %}
   {% set choices=['day','cosy','Candle'] + (catalog.effects.keys()|reject('in',['Candle','Colour loop','Breathe','Normal light'])|list) %}
   {% set group=current.plan.resolved.targets.get('room:'~room,{}) %}
   {% set selected=value.get('selection',group.get('period','day')) %}
   {% set index=choices.index(selected) if selected in choices else 0 %}
   {% set selected=choices[(index+(1 if command=='right' else -1)) % (choices|count)] %}
   {% set n.value=dict(n.value,selection=selected,selection_updated=stamp) %}
   {% if selected in ['day','cosy'] %}
    {% set n.value=dict(n.value,period=selected,period_updated=stamp,adjustment=dict(identity,anchor=selected),selection_input=none) %}
   {% else %}
    {% set n.value=dict(n.value,selection_input=a.v,selection_instance=source~':'~selected,adjustment=none) %}
   {% endif %}
  {% endif %}
  {% set S=current.plan.get('schedule_details',{}).get(room,{}) %}
  {% if S %}{% set n.value=dict(n.value,remote_valid_until=S.get('next_fs',0),remote_timing_revision=timing_revision) %}{% endif %}
  {% set n.result={'op':'set','records':[{'kind':'input','key':key,'source':source,'scope':'room','target':room,'value':n.value}],'via':'remote'} %}
 {% endif %}
{% endif %}
{{ n.result }}

{# Shared build-time source embedded into the two pure HA script templates. #}
{% macro color_json(color) -%}
  {{- ({'kelvin':color.kelvin} if 'kelvin' in color else {'rgb':color.rgb|list})|to_json -}}
{%- endmacro %}

{% macro rgb_value(color) -%}
  {%- if 'rgb' in color -%}
    {{- color.rgb|list|to_json -}}
  {%- else -%}
    {%- set t = color.kelvin / 100 -%}
    {%- set r = 255 if t <= 66 else 329.698727446 * ((t-60) ** -0.1332047592) -%}
    {%- set g = 99.4708025861 * (t|log) - 161.1195681661 if t <= 66 else 288.1221695283 * ((t-60) ** -0.0755148492) -%}
    {%- set b = 255 if t >= 66 else 0 if t <= 19 else 138.5177312231 * ((t-10)|log) - 305.0447927307 -%}
    {{- [[0,[255,r]|min]|max|round|int, [0,[255,g]|min]|max|round|int, [0,[255,b]|min]|max|round|int]|to_json -}}
  {%- endif -%}
{%- endmacro %}

{% macro mix_color(a, b, amount) -%}
  {%- if amount <= 0 -%}{{- color_json(a) -}}
  {%- elif amount >= 1 -%}{{- color_json(b) -}}
  {%- elif 'kelvin' in a and 'kelvin' in b -%}
    {{- {'kelvin': a.kelvin + (b.kelvin-a.kelvin)*amount}|to_json -}}
  {%- else -%}
    {%- set left=rgb_value(a)|from_json -%}
    {%- set right=rgb_value(b)|from_json -%}
    {{- {'rgb': [(left[0]+(right[0]-left[0])*amount)|round|int, (left[1]+(right[1]-left[1])*amount)|round|int, (left[2]+(right[2]-left[2])*amount)|round|int]}|to_json -}}
  {%- endif -%}
{%- endmacro %}

{% macro scale_value(day, cosy, position, warm_end) -%}
  {%- set p = [-2,[2,position]|min]|max -%}
  {%- if p == 0 -%}
    {%- set brightness=cosy.brightness -%}{%- set color=cosy.color -%}
  {%- elif p == 1 -%}
    {%- set brightness=day.brightness -%}{%- set color=day.color -%}
  {%- elif p > 1 -%}
    {%- set brightness=day.brightness+(255-day.brightness)*(p-1) -%}
    {%- set color=mix_color(day.color, {'kelvin':6500}, p-1)|from_json -%}
  {%- elif p > 0 -%}
    {%- set brightness=cosy.brightness+(day.brightness-cosy.brightness)*p -%}
    {%- set color=mix_color(cosy.color,day.color,p)|from_json -%}
  {%- else -%}
    {# Preserve configured anchors below the normal floor; moving down must never brighten them. #}
    {%- set floor=[76.5,cosy.brightness]|min -%}
    {%- set slope=[0,day.brightness-cosy.brightness,(cosy.brightness-floor)/2]|max -%}
    {%- set brightness=[floor,cosy.brightness+p*slope]|max -%}
    {%- if p <= -1 -%}
      {%- set color=mix_color({'rgb':[255,134,7]}, {'rgb':warm_end}, -p-1)|from_json -%}
    {%- elif 'kelvin' in cosy.color and cosy.color.kelvin >= 1950 -%}
      {%- set color={'kelvin':cosy.color.kelvin+(1950-cosy.color.kelvin)*(-p)} -%}
    {%- else -%}
      {%- set color=mix_color(cosy.color, {'rgb':[255,134,7]}, -p)|from_json -%}
    {%- endif -%}
  {%- endif -%}
  {{- {'brightness':[0,[255,brightness]|min]|max, 'color':color_json(color)|from_json, 'position':p}|to_json -}}
{%- endmacro %}

{# Compile only on anchor changes. Sampling retains the original arithmetic order. #}
{% macro gradient_signature(day,cosy,warm_end) -%}
 {{- [1,day.brightness,color_json(day.color)|from_json,cosy.brightness,color_json(cosy.color)|from_json,warm_end|list]|to_json -}}
{%- endmacro %}

{% macro gradient_color(left,right) -%}
 {%- set a=color_json(left)|from_json -%}{%- set b=color_json(right)|from_json -%}
 {%- if 'kelvin' in a and 'kelvin' in b -%}
  {{- {'left':a,'right':b,'kind':'kelvin','start':a.kelvin,'delta':b.kelvin-a.kelvin}|to_json -}}
 {%- else -%}
  {%- set x=rgb_value(a)|from_json -%}{%- set y=rgb_value(b)|from_json -%}
  {{- {'left':a,'right':b,'kind':'rgb','start':x,'delta':[y[0]-x[0],y[1]-x[1],y[2]-x[2]]}|to_json -}}
 {%- endif -%}
{%- endmacro %}

{% macro gradient_compile(day,cosy,warm_end) -%}
 {%- set floor=[76.5,cosy.brightness]|min -%}
 {%- set crossover={'rgb':[255,134,7]} -%}
 {%- set lower={'kelvin':1950} if 'kelvin' in cosy.color and cosy.color.kelvin>=1950 else crossover -%}
 {{- {'version':1,
       'day':{'brightness':day.brightness,'color':color_json(day.color)|from_json},
       'cosy':{'brightness':cosy.brightness,'color':color_json(cosy.color)|from_json},
       'brightness':{'floor':floor,'lower':[0,day.brightness-cosy.brightness,(cosy.brightness-floor)/2]|max,'middle':day.brightness-cosy.brightness,'upper':255-day.brightness},
       'colors':{'lower':gradient_color(cosy.color,lower)|from_json,'middle':gradient_color(cosy.color,day.color)|from_json,'upper':gradient_color(day.color,{'kelvin':6500})|from_json,'tail':gradient_color(crossover,{'rgb':warm_end})|from_json}}|to_json -}}
{%- endmacro %}

{% macro gradient_color_valid(color) -%}
 {%- set n=namespace(ok=color is mapping) -%}
 {%- if n.ok -%}
  {%- if 'kelvin' in color and 'rgb' not in color -%}
   {%- set n.ok=color.kelvin is number and color.kelvin is not boolean and 0<color.kelvin<1e20 -%}
  {%- elif 'rgb' in color and 'kelvin' not in color and color.rgb is sequence and color.rgb is not string and color.rgb is not mapping and color.rgb|count==3 -%}
   {%- for v in color.rgb -%}{%- if v is not number or v is boolean or not (0<=v<=255) -%}{%- set n.ok=false -%}{%- endif -%}{%- endfor -%}
  {%- else -%}{%- set n.ok=false -%}{%- endif -%}
 {%- endif -%}
 {{- n.ok|to_json -}}
{%- endmacro %}

{% macro gradient_valid(entry,signature) -%}
 {# Cache is our own compiled data: validate version, anchor identity and complete shape.
    Never recompute Kelvin conversions to validate a cache hit. #}
 {%- set n=namespace(ok=entry is mapping) -%}
 {%- if n.ok -%}{%- set n.ok=entry.get('signature')==signature and entry.get('curve') is mapping -%}{%- endif -%}
 {%- if n.ok -%}
  {%- set c=entry.curve -%}
  {%- set n.ok=c.get('version')==1 and c.get('day') is mapping and c.get('cosy') is mapping and c.get('brightness') is mapping and c.get('colors') is mapping -%}
  {%- if n.ok -%}
   {%- set n.ok=c.day.get('brightness')==signature[1] and c.day.get('color')==signature[2] and c.cosy.get('brightness')==signature[3] and c.cosy.get('color')==signature[4] -%}
   {%- for name in ['floor','lower','middle','upper'] -%}
    {%- set v=c.brightness.get(name) -%}{%- if v is not number or v is boolean or not (-1e20<v<1e20) -%}{%- set n.ok=false -%}{%- endif -%}
   {%- endfor -%}
   {%- for name in ['lower','middle','upper','tail'] -%}
    {%- set piece=c.colors.get(name) -%}
    {%- if piece is not mapping -%}{%- set n.ok=false -%}
    {%- else -%}
     {%- if not (gradient_color_valid(piece.get('left'))|from_json) or not (gradient_color_valid(piece.get('right'))|from_json) -%}{%- set n.ok=false -%}{%- endif -%}
     {%- if piece.get('kind')=='kelvin' -%}
      {%- for field in ['start','delta'] -%}{%- set v=piece.get(field) -%}{%- if v is not number or v is boolean or not (-1e20<v<1e20) -%}{%- set n.ok=false -%}{%- endif -%}{%- endfor -%}
     {%- elif piece.get('kind')=='rgb' -%}
      {%- for field in ['start','delta'] -%}
       {%- set values=piece.get(field) -%}
       {%- if values is not sequence or values is string or values is mapping or values|count!=3 -%}{%- set n.ok=false -%}
       {%- else -%}{%- for v in values -%}{%- if v is not number or v is boolean or not (-1e20<v<1e20) -%}{%- set n.ok=false -%}{%- endif -%}{%- endfor -%}{%- endif -%}
      {%- endfor -%}
     {%- else -%}{%- set n.ok=false -%}{%- endif -%}
    {%- endif -%}
   {%- endfor -%}
  {%- endif -%}
 {%- endif -%}
 {{- n.ok|to_json -}}
{%- endmacro %}

{% macro gradient_color_sample(piece,amount) -%}
 {%- if amount<=0 -%}{{- piece.left|to_json -}}
 {%- elif amount>=1 -%}{{- piece.right|to_json -}}
 {%- elif piece.kind=='kelvin' -%}{{- {'kelvin':piece.start+piece.delta*amount}|to_json -}}
 {%- else -%}{{- {'rgb':[(piece.start[0]+piece.delta[0]*amount)|round|int,(piece.start[1]+piece.delta[1]*amount)|round|int,(piece.start[2]+piece.delta[2]*amount)|round|int]}|to_json -}}
 {%- endif -%}
{%- endmacro %}

{% macro gradient_sample(curve,position) -%}
 {%- set p=[-2,[2,position]|min]|max -%}
 {%- if p==0 -%}{%- set brightness=curve.cosy.brightness -%}{%- set color=curve.cosy.color -%}
 {%- elif p==1 -%}{%- set brightness=curve.day.brightness -%}{%- set color=curve.day.color -%}
 {%- elif p>1 -%}
  {%- set brightness=curve.day.brightness+curve.brightness.upper*(p-1) -%}
  {%- set color=gradient_color_sample(curve.colors.upper,p-1)|from_json -%}
 {%- elif p>0 -%}
  {%- set brightness=curve.cosy.brightness+curve.brightness.middle*p -%}
  {%- set color=gradient_color_sample(curve.colors.middle,p)|from_json -%}
 {%- else -%}
  {%- set brightness=[curve.brightness.floor,curve.cosy.brightness+p*curve.brightness.lower]|max -%}
  {%- set color=gradient_color_sample(curve.colors.tail,-p-1)|from_json if p<=-1 else gradient_color_sample(curve.colors.lower,-p)|from_json -%}
 {%- endif -%}
 {{- {'brightness':[0,[255,brightness]|min]|max,'color':color,'position':p}|to_json -}}
{%- endmacro %}

{# One logical input stream per room; each source keeps a bounded snapshot.
   The most recent snapshot includes preceding inputs from the room's other
   remotes, so alternating devices cannot drop or apply a click twice. #}
{% macro latest_remote_key(records,room) -%}
 {% set pick=namespace(key='',stamp=-1) %}
 {% for key,r in records|dictsort if r is mapping and r.get('scope')=='room' and r.get('target')==room and (r.get('kind')=='input' or (r.get('kind')=='channels' and r.get('via')=='remote')) %}
  {% set stamp=as_timestamp(r.get('when'),0) %}
  {% if stamp>=pick.stamp %}{% set pick.key=key %}{% set pick.stamp=stamp %}{% endif %}
 {% endfor %}
 {{- pick.key|to_json -}}
{%- endmacro %}

{# Pure Normal Light processor. The adapter stores ticks; only this processor knows
   how ticks map to the Day/Cosy gradient. Animation processors default to no-op. #}
{% macro normal_position(input, item, level) -%}
 {% set d=item.day.brightness-item.cosy.brightness %}
 {% set floor=[76.5,item.cosy.brightness]|min %}
 {% set slope=[0,d,(item.cosy.brightness-floor)/2]|max %}
 {% if input.get('anchor')=='day' %}{% set seed=1 %}
 {% elif input.get('anchor')=='cosy' %}{% set seed=0 %}
 {% elif input.get('legacy_position') is number %}{% set seed=input.legacy_position %}
 {% elif level>item.day.brightness and item.day.brightness<255 %}{% set seed=1+(level-item.day.brightness)/(255-item.day.brightness) %}
 {% elif level<item.cosy.brightness and slope>0 %}{% set seed=[-2,(level-item.cosy.brightness)/slope]|max %}
 {% else %}{% set seed=(level-item.cosy.brightness)/d if d>0 else 1 %}{% endif %}
 {{- ([input.lower,[input.upper,seed*10+input.steps]|min]|max/10)|to_json -}}
{%- endmacro %}

{% macro input_claims(value,key,stamp) -%}
 {% set n=namespace(claims=[]) %}
 {% if value.get('selection') not in ['day','cosy',none] and value.get('legacy_channels') is not mapping %}
  {% if value.get('selection_input') is mapping %}
   {% set n.claims=n.claims+[{'kind':'input','input':value.selection_input,'updated':value.selection_input.get('updated',stamp)}] %}
  {% endif %}
  {% set n.claims=n.claims+[{'kind':'effect','effect':value.selection,'instance':value.get('selection_instance',key~':'~value.selection),'updated':value.get('selection_updated',stamp)}] %}
 {% endif %}
 {% if value.get('adjustment') is mapping %}
  {% set n.claims=n.claims+[{'kind':'input','input':value.adjustment,'updated':value.adjustment.get('updated',stamp)}] %}
 {% endif %}
 {{- n.claims|to_json -}}
{%- endmacro %}

{# No time, state, service or event access. Only record timestamps are interpreted. #}
{% macro valid_color(c) -%}
  {%- set v=namespace(ok=false) -%}
  {%- if c is mapping -%}
    {%- if 'kelvin' in c and 'rgb' not in c and c.kelvin is number and c.kelvin is not boolean and c.kelvin >= 1000 and c.kelvin <= 10000 -%}
      {%- set v.ok=true -%}
    {%- elif 'rgb' in c and 'kelvin' not in c and c.rgb is sequence and c.rgb is not string and c.rgb is not mapping and c.rgb|count == 3 -%}
      {%- set v.ok=true -%}
      {%- for component in c.rgb -%}
        {%- if component is not number or component is boolean or component < 0 or component > 255 or component != component -%}{%- set v.ok=false -%}{%- endif -%}
      {%- endfor -%}
    {%- endif -%}
  {%- endif -%}
  {{- v.ok|to_json -}}
{%- endmacro %}

{% macro effect_channels(name) -%}
  {%- set d=catalog.effects.get(name,{}) if name is string else {} -%}
  {%- set channels=d.get('channels',[]) if d is mapping else [] -%}
  {%- set v=namespace(ok=channels is sequence and channels is not string and channels is not mapping and channels|count > 0) -%}
  {%- if v.ok -%}
    {%- for channel in channels -%}{%- if channel not in ['brightness','color'] -%}{%- set v.ok=false -%}{%- endif -%}{%- endfor -%}
  {%- endif -%}
  {{- (channels|list if v.ok else [])|to_json -}}
{%- endmacro %}


